boost::asio::io_context io;
boost::asio::ip::tcp::acceptor acc(io, tcp::endpoint(tcp::v4(), 8080));

std::function<void()> accept_next = [&] {
    acc.async_accept([&](error_code ec, tcp::socket s) {
        if (!ec) std::make_shared<Session>(std::move(s))->start();  /* handler per handle */
        accept_next();                                              /* re-arm from the handler */
    });
};
accept_next();
io.run();                                   /* dispatcher loop; handlers run on this thread */

