for (;;) {
    int n = epoll_wait(epfd, evs, MAX_EVENTS, -1);              /* demultiplex */
    for (int i = 0; i < n; ++i) {
        auto it = handlers.find(evs[i].data.fd);
        if (it != handlers.end()) it->second(evs[i].events);    /* dispatch */
